'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { HoverCard } from '@/registry/satin/ui/hover-card'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Citations and sources, 1:1 with the uiKit design (🆕 citations): where an answer comes from.
 *
 * - `Citation`: a numbered chip right after the claim — 16 high, text/xs medium on bg/muted,
 *   radius-sm; hover bg/hover with a border/strong ring. Resting on it (or focusing it) opens a
 *   HoverCard with the source: logo and where it lives, the title, and the quoted passage.
 * - `Sources`: under the message, a pill with the sources' logos stacked and "3 sources"; it
 *   opens into the list — number, logo, title, where it lives — each row a link.
 *
 * A source's `icon` is its logo (an app's or a site's favicon); without one it gets a tile with
 * its first letter, so a missing favicon never leaves a hole.
 */
export interface CitationSource {
  title: string
  /** Where it comes from: the app or site, "Notion" or "freshfarm.pl". */
  origin?: string
  href?: string
  /** A 16px logo or favicon. */
  icon?: React.ReactNode
  /** The passage the answer relies on, shown in the preview. */
  quote?: string
}

function SourceIcon({ source }: { source: CitationSource }) {
  if (source.icon) return <span className="sa:grid sa:size-4 sa:shrink-0 sa:place-items-center sa:overflow-clip sa:rounded-xs sa:[&>*]:size-4">{source.icon}</span>
  return (
    <span aria-hidden className="sa:grid sa:size-4 sa:shrink-0 sa:place-items-center sa:rounded-xs sa:bg-bg-muted sa:text-[10px] sa:leading-none sa:font-semibold sa:text-text-muted">
      {source.title.charAt(0).toUpperCase()}
    </span>
  )
}

/** The numbered chip. Other props, `ref` included, go to its `a` (an `aria-label` passed in replaces the default). */
export interface CitationProps extends Omit<React.ComponentProps<'a'>, 'children'> {
  /** 1-based, as in the Sources list. */
  index: number
  source: CitationSource
  className?: string
}

export function Citation({ index, source, className, 'aria-label': ariaLabel, ...props }: CitationProps) {
  const labels = useSatinLabels()
  const chip = (
    <a
      {...props}
      data-slot="citation"
      href={source.href}
      target={source.href ? '_blank' : undefined}
      rel={source.href ? 'noreferrer' : undefined}
      aria-label={ariaLabel ?? `${labels.source} ${index}: ${source.title}`}
      className={cn(
        'sa:mx-0.5 sa:inline-grid sa:h-4 sa:min-w-4 sa:translate-y-[-1px] sa:place-items-center sa:rounded-sm sa:bg-bg-muted sa:px-1 sa:align-middle sa:text-xs sa:leading-none sa:font-medium sa:text-text-default sa:no-underline sa:tabular-nums sa:outline-none',
        'sa:transition-[background-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        'sa:hover:bg-bg-hover sa:hover:[box-shadow:inset_0_0_0_1px_var(--sa-border-strong)] sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
        className,
      )}
    >
      {index}
    </a>
  )
  return (
    <HoverCard trigger={chip} side="top" align="center" className="sa:w-[300px] sa:gap-2 sa:p-3">
      <span className="sa:flex sa:items-center sa:gap-2 sa:text-xs sa:text-text-muted">
        <SourceIcon source={source} />
        <span className="sa:truncate">{source.origin}</span>
      </span>
      <span className="sa:text-sm sa:font-medium sa:text-text-default">{source.title}</span>
      {source.quote && <span className="sa:text-body sa:text-text-muted">“{source.quote}”</span>}
    </HoverCard>
  )
}

/** The sources pill and list. Other props, `ref` included, go to its root `div`. */
export interface SourcesProps extends Omit<React.ComponentProps<'div'>, 'children'> {
  sources: CitationSource[]
  /** Start with the list open. */
  defaultOpen?: boolean
  className?: string
}

export function Sources({ sources, defaultOpen = false, className, ...props }: SourcesProps) {
  const labels = useSatinLabels()
  const [open, setOpen] = React.useState(defaultOpen)
  const listId = React.useId()
  return (
    <div {...props} data-slot="sources" className={cn('sa:flex sa:flex-col sa:gap-2', className)}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen(!open)}
        className={cn(
          'sa:inline-flex sa:h-8 sa:w-fit sa:items-center sa:gap-2 sa:rounded-pill sa:border sa:border-border-default sa:py-1 sa:ps-1.5 sa:pe-3 sa:text-sm sa:font-medium sa:text-text-default sa:outline-none',
          'sa:transition-[border-color,background-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
          'sa:hover:border-border-strong sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          open && 'sa:bg-bg-hover',
        )}
      >
        <span className="sa:flex sa:items-center sa:gap-0.5">
          {sources.slice(0, 3).map((s, i) => (
            <SourceIcon key={i} source={s} />
          ))}
        </span>
        {labels.sourcesCount(sources.length)}
      </button>
      <div id={listId} data-state={open ? 'open' : 'closed'} className="satin-expand">
        <div>
          <ol className="sa:flex sa:flex-col sa:gap-0.5">
            {sources.map((s, i) => (
              <li key={i}>
                <a
                  href={s.href}
                  target={s.href ? '_blank' : undefined}
                  rel={s.href ? 'noreferrer' : undefined}
                  className="sa:flex sa:items-center sa:gap-3 sa:rounded-lg sa:p-2 sa:text-sm sa:no-underline sa:outline-none sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out) sa:hover:bg-bg-hover sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]"
                >
                  <span className="sa:grid sa:h-4 sa:min-w-4 sa:place-items-center sa:rounded-sm sa:bg-bg-muted sa:px-1 sa:text-xs sa:leading-none sa:font-medium sa:text-text-default sa:tabular-nums">{i + 1}</span>
                  <SourceIcon source={s} />
                  <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-text-default">{s.title}</span>
                  {s.origin && <span className="sa:shrink-0 sa:text-text-muted">{s.origin}</span>}
                </a>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </div>
  )
}
